import java.util.*;
import java.io.*;

public class CF552C {
  public static int maxPowerIndex, baseVal;
  public static Set<Long> sumSet;
  public static void main(String[] args) throws Exception {
    Scanner sc = new Scanner(System.in);
    PrintWriter pw = new PrintWriter(System.out);

    int baseInput = sc.nextInt();
    long targetInput = sc.nextLong();

    int maxPower = 0;
    for (int i = 0; baseInput > 2 && i < 21; i++) {
      maxPower = i;
      if (Math.pow(baseInput, i) > 1e9) break;
    }

    sumSet = new HashSet<>();
    if (baseInput > 2) generateSums(0, 0, maxPower);

    boolean answer = false;
    if (baseInput == 2) answer = true;

    for (Long val : sumSet) {
      if (val >= targetInput && sumSet.contains(val - targetInput)) {
        answer = true;
        break;
      }
    }

    pw.println(answer ? "YES" : "NO");
    pw.close();
  }

  static void generateSums(int index, long sum, int maxExp) {
    if (index > maxExp) {
      sumSet.add(sum);
      return;
    }
    generateSums(index + 1, sum + (long) Math.pow(baseVal, index), maxExp);
    generateSums(index + 1, sum, maxExp);
  }
}
